#!/bin/bash
# Publish the Nolan site: copy the built folder into the deploy clone and push it.
#
#   bash /Users/triton/PROTEUS/bin/publish-nolan.sh "commit message"
#
# Source of truth is /Users/triton/PROTEUS/sites/builds/nolan/ (generated by sites/nolan/build.cjs and
# committed in proteus-lab). The deploy target is a gitignored clone of github.com/triton-xxix/proteus-nolan
# at sandbox/proteus-nolan, served by GitHub Pages from main at /. Every command here is on the unattended
# hook's safe list, so the nightly can republish. Honours HALT. Same shape as bin/mirror-vault.sh.
set -u
ROOT=/Users/triton/PROTEUS
SRC="$ROOT/sites/builds/nolan"
DEPLOY="$ROOT/sandbox/proteus-nolan"
MSG="${1:-Nolan site: rebuild}"
LOG="$ROOT/state/runs/$(date +%F).md"

if [ -f "$ROOT/HALT" ]; then
  echo "HALT is set: not publishing"
  exit 0
fi
if [ ! -d "$DEPLOY/.git" ]; then
  echo "no deploy clone at $DEPLOY (gh repo clone triton-xxix/proteus-nolan $DEPLOY)"
  exit 1
fi
if [ ! -f "$SRC/index.html" ]; then
  echo "nothing built at $SRC"
  exit 1
fi

git -C "$DEPLOY" checkout -q -B main
/usr/bin/rsync -a --delete \
  --exclude .git --exclude lab --exclude node_modules --exclude BRIEF.md \
  --exclude package.json --exclude package-lock.json \
  "$SRC/" "$DEPLOY/"
git -C "$DEPLOY" add -A
if git -C "$DEPLOY" diff --cached --quiet; then
  echo "publish-nolan: nothing changed"
  exit 0
fi
git -C "$DEPLOY" -c user.name=Proteus -c user.email=259466468+triton-xxix@users.noreply.github.com commit -q -m "$MSG"
git -C "$DEPLOY" push -q -u origin main
SHA=$(git -C "$DEPLOY" rev-parse --short HEAD)
echo "publish-nolan: pushed $SHA ($MSG)"
mkdir -p "$ROOT/state/runs"
printf -- '- Nolan site published: %s, proteus-nolan %s.\n' "$MSG" "$SHA" >> "$LOG"
